import * as React from "react"

import { cn } from "@/lib/utils"

type TilingProps = React.ComponentProps<"div"> & {
  /** rules: one hairline between tiles, as "Less is more." divides its sheet. crosses: no lines, a registration cross where the tiles' corners meet. */
  variant?: "rules" | "crosses"
}

/**
 * Tiles on the 12-column grid, held apart by space and one hairline, never boxed. A tiling covers the plane with
 * no gaps and no overlaps, so neighbours share an edge: each tile draws only its start and top edge, halfway into
 * the gap, and the edges that meet the tiling's own border are clipped away.
 */
function Tiling({ variant = "rules", className, children, ...props }: TilingProps) {
  // The sheet is the grid; the outer box is the container its narrow layouts are measured against.
  return (
    <div data-slot="tiling" data-variant={variant} className={cn("db-tiling", className)} {...props}>
      <div className="db-tiling-sheet">{children}</div>
    </div>
  )
}

type TileProps = React.ComponentProps<"div"> & {
  /** Columns out of 12. In a narrow tiling a tile of 6 or fewer takes half, a wider one the whole width. */
  span?: number
  /** Rows it stands through. */
  rows?: number
  /** The corner its content keeps to, as the poster keeps its notes. A child with margin-block-start: auto goes to the foot. */
  place?: "start-top" | "end-top" | "start-foot" | "end-foot"
}

function Tile({ span = 4, rows = 1, place = "start-top", className, style, ...props }: TileProps) {
  return (
    <div
      data-slot="tile"
      data-place={place}
      className={cn("db-tile", className)}
      style={{ "--span": span, "--rows": rows, ...style } as React.CSSProperties}
      {...props}
    />
  )
}

export { Tiling, Tile, type TilingProps, type TileProps }

@layer components {
  /* ── db-tiling ── tiles on the 12-column grid, held apart by space and one hairline, never boxed, after "Less is more.".
     A tiling has no gaps and no overlaps, so neighbours share an edge: each tile draws its start and top edge halfway into the gap,
     and the one line serves both sides. The edges that fall on the tiling's own border lie half a gap outside it and are clipped,
     so no frame is drawn round the whole; the lines that stay run a step past the edge, as a draughtsman's construction lines do. */
  .db-tiling { --gap: var(--db-space-6); --line: var(--db-ink); --over: var(--db-space-2); container-type: inline-size; min-width: 0; }
  .db-tiling-sheet {
    display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); grid-auto-rows: minmax(var(--db-space-8), auto); gap: var(--gap);
    clip-path: inset(calc(-1 * var(--over)));
  }
  .db-tile { position: relative; display: flex; flex-direction: column; align-items: flex-start; min-width: 0; grid-column: span min(var(--span, 4), 12); grid-row: span var(--rows, 1); }
  /* The top edge whole, the start edge under it, so no two lines ever cover one pixel twice. */
  .db-tile::before {
    content: ""; position: absolute; inset: calc(var(--gap) / -2); pointer-events: none;
    background:
      linear-gradient(var(--line), var(--line)) 0 0 / 100% var(--db-hairline) no-repeat,
      linear-gradient(var(--line), var(--line)) 0 var(--db-hairline) / var(--db-hairline) calc(100% - var(--db-hairline)) no-repeat;
  }
  .db-tile:is([dir="rtl"], [dir="rtl"] *)::before { background-position: 0 0, 100% var(--db-hairline); }
  /* The corner the content keeps to. */
  .db-tile[data-place^="end"] { align-items: flex-end; text-align: end; }
  .db-tile[data-place$="foot"] { justify-content: flex-end; }
  /* Narrow: twelve columns' gaps alone would outgrow the sheet, so it falls to two: a tile of up to half the grid takes one, a
     wider one both; narrower still, one column, every tile the whole width and one row high. */
  @container (width < 40rem) { .db-tiling-sheet { grid-template-columns: repeat(2, minmax(0, 1fr)); } .db-tile { grid-column: span clamp(1, (var(--span, 4) - 6) * 2, 2); } }
  @container (width < 24rem) { .db-tiling-sheet { grid-template-columns: minmax(0, 1fr); } .db-tile { grid-column: auto; grid-row: auto; } }

  /* crosses: after "the uncreative", which marks the corners of its block with + signs. No lines: the space alone holds the tiles
     apart, and a registration cross stands at every corner of every tile, in the pencil, the outer ones a half gap outside the block. */
  .db-tiling[data-variant="crosses"] > .db-tiling-sheet { clip-path: none; }
  .db-tiling[data-variant="crosses"] .db-tile::before {
    --x: calc(var(--db-space-3) + var(--db-hairline)); --h: calc(var(--x) / 2 - var(--db-hairline) / 2); --c: var(--db-pencil);
    inset: calc(var(--gap) / -2 - var(--x) / 2);
    background:
      linear-gradient(var(--c), var(--c)) left 0 top var(--h) / var(--x) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) left var(--h) top 0 / var(--db-hairline) var(--x),
      linear-gradient(var(--c), var(--c)) right 0 top var(--h) / var(--x) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) right var(--h) top 0 / var(--db-hairline) var(--x),
      linear-gradient(var(--c), var(--c)) left 0 bottom var(--h) / var(--x) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) left var(--h) bottom 0 / var(--db-hairline) var(--x),
      linear-gradient(var(--c), var(--c)) right 0 bottom var(--h) / var(--x) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) right var(--h) bottom 0 / var(--db-hairline) var(--x);
    background-repeat: no-repeat;
  }

  /* Forced colours would drop the lines and crosses, which are background images: keep them, in CanvasText. */
  @media (forced-colors: active) { .db-tiling { --line: CanvasText; } .db-tiling[data-variant="crosses"] .db-tile::before { --c: CanvasText; } .db-tile::before { forced-color-adjust: none; } }
}
